('App\\Models\\CareerBenefits', 3, 'ar', 'description', NULL, 'تغطية كاملة لك ولعائلتك.', 498),
('App\\Models\\CareerJob', 24, 'ar', 'title', NULL, 'مطور جافا', 500),
('App\\Models\\CareerJob', 24, 'ar', 'job_description', NULL, '<div>المهارات والمعارف:</div><div>برمجة PHP: يُعدّ الفهم المتعمق للغة PHP أمرًا أساسيًا.</div><div>إطار عمل لارافيل: خبرة في استخدام ميزات ووظائف لارافيل.</div><div>إدارة قواعد البيانات: خبرة في قواعد البيانات العلائقية ولغة SQL.</div><div>التحكم في الإصدارات: استخدام أدوات مثل Git لإدارة الأكواد البرمجية والتعاون.</div><div>أساسيات تطوير الويب: تُعد لغات HTML وCSS وJavaScript مهمة أيضًا.</div><div>مهارات حل المشكلات والتحليل: القدرة على تشخيص المشكلات وإصلاحها في تطبيقات الويب.</div>', 501),
