('App\\Models\\Product', 24, 'ar', 'description', NULL, '<section class=\"ls section_padding_100 section_padding_bottom_0 columns_padding_30\" hacen=\"\" saudi=\"\" arabia\";=\"\" font-size:=\"\" 16px;\"=\"\" style=\"color: rgb(51, 51, 51); overflow: hidden;\"><div class=\"container white_container\" style=\"width: 1170px; padding-top: 100px; padding-bottom: 0px;\"><div class=\"row\" style=\"margin-right: -30px; margin-left: -30px;\"><div class=\"col-sm-8 col-lg-12\" style=\"width: 1200px; padding-right: 30px; padding-left: 30px; min-height: 1px; float: right; margin-top: 10px; margin-bottom: 10px;\"><p class=\"desc\" style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px 47px;\">بطارية \"محكمة الاغلاق \" مناسبة لنماذج السيارات من العلامات التجارية الآسيوية. بطاريات خالية من الصيانة، تمنح أداء عالي. وشملت العين السحريه (مؤشر حالة البطارية).</p></div></div></div></section><section class=\"ls section_padding_top_0 section_padding_bottom_0 columns_padding_30\" hacen=\"\" saudi=\"\" arabia\";=\"\" font-size:=\"\" 16px;\"=\"\" style=\"color: rgb(51, 51, 51); overflow: hidden;\"><div class=\"container white_container\" style=\"width: 1170px; padding-top: 0px; padding-bottom: 0px;\"><div class=\"row\" style=\"margin-right: -30px; margin-left: -30px;\"><div class=\"col-sm-9 col-md-10 col-sm-push-2 col-md-push-1\" style=\"width: 1000px; padding-right: 30px; padding-left: 30px; flex-basis: 83.3333%; max-width: 83.3333%; min-height: 1px; float: right; left: 0px; margin-top: 10px; margin-bottom: 10px; right: 99.9896px;\"><div itemscope=\"\" itemtype=\"#\" class=\"product type-product row\"><div class=\"images col-sm-6\" style=\"position: static; width: 485px; min-height: 1px; float: right; margin-top: 10px; margin-bottom: 10px;\"><img src=\"data:image/png;base64,\" data-filename=\"el nisr N90.png\" style=\"width: 686.003px;\"></div></div></div></div></div></section>', 751),
