CREATE TABLE `warranties` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `warranty_public_id` varchar(255) DEFAULT NULL,
  `policy_version` varchar(255) DEFAULT NULL,
  `consent_checked` tinyint(1) NOT NULL DEFAULT 0,
  `consent_timestamp` datetime DEFAULT NULL,
  `consent_ip` varchar(255) DEFAULT NULL,
  `serial_number` varchar(255) NOT NULL,
  `warranty_months` int(11) DEFAULT NULL,
  `product_id` int(11) DEFAULT NULL,
  `product_stock_id` bigint(20) UNSIGNED DEFAULT NULL,
  `status` enum('preactivated','active','cancelled','replaced','expired','pending_review') DEFAULT 'preactivated',
  `activation_date` timestamp NULL DEFAULT NULL,
  `start_date` timestamp NULL DEFAULT NULL,
  `end_date` timestamp NULL DEFAULT NULL,
  `final_user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `distributor_id` bigint(20) UNSIGNED DEFAULT NULL,
  `branch_id` bigint(20) UNSIGNED DEFAULT NULL,
  `activated_by_name` varchar(255) DEFAULT NULL,
  `activated_by_phone` varchar(255) DEFAULT NULL,
  `activated_by_email` varchar(255) DEFAULT NULL,
  `activated_ip` varchar(255) DEFAULT NULL,
  `activation_method` varchar(255) DEFAULT NULL,
  `is_admin_manual_activation` tinyint(1) NOT NULL DEFAULT 0,
  `is_admin_override` tinyint(1) NOT NULL DEFAULT 0,
  `original_warranty_id` bigint(20) UNSIGNED DEFAULT NULL,
  `purchase_date` date DEFAULT NULL,
  `retailer_name` varchar(255) DEFAULT NULL,
  `retailer_branch_id` bigint(20) UNSIGNED DEFAULT NULL,
  `invoice_number` varchar(255) DEFAULT NULL,
  `receipt_path` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

